            case '/api/cart':return $this->cart->get($this->cartToken,$r->query->get('currency','TRY'),$this->principal?->id);
            case '/api/products':return (new Catalog($this->db,$this->config))->search($r->query->all());
            case '/api/markets':return ['countries'=>$this->db->all('SELECT code,name,currency,shipping_minor FROM country_rules WHERE enabled=true AND product_approved=true AND age_approved=true AND payment_approved=true AND shipping_approved=true AND tax_approved=true AND legal_approved=true AND(fixture=false OR ?=true)',[$this->config->local()?1:0])];
            case '/api/admin/catalog':RuleViolation::ensure($this->principal,'AUTH_REQUIRED','Giriş yapın.',401);return ['rows'=>(new Catalog($this->db,$this->config))->admin($this->principal)];
            default:if(preg_match('~^/api/admin/orders/([A-Za-z0-9-]+)$~',$path,$m))return (new Fulfillment($this->db,$this->config))->detail($m[1],$this->actor('orders'));if(preg_match('~^/api/orders/([A-Za-z0-9-]+)$~',$path,$m)){$order=$this->commerce->order($m[1],$r->query->get('token'),$this->principal?->id);RuleViolation::ensure($order,'ORDER_NOT_FOUND','Sipariş bulunamadı.',404);return $order;}throw new RuleViolation('NOT_FOUND','İşlem bulunamadı.',404);
        }
    }
    private function page(string $path,Request $r):Response
    {
        $catalog=new Catalog($this->db,$this->config);
        if($path==='/yonetim/ice-aktarim'){$actor=$this->actor('catalog');return $this->render('import-admin',['title'=>'Ürün içe aktarma','rows'=>(new Import($this->db,$this->config))->listing($actor),'columns'=>Import::COLUMNS,'batch'=>null]);}
        if($path==='/yonetim/ice-aktarim/sablon.csv'){$this->actor('catalog');return new Response(Import::csv([array_values(Import::COLUMNS)]),200,['Content-Type'=>'text/csv; charset=UTF-8','Content-Disposition'=>"attachment; filename=product-template.csv; filename*=UTF-8''".rawurlencode('ürün-şablonu.csv')]);}
        if(preg_match('~^/yonetim/ice-aktarim/([A-Za-z0-9-]+)(/hatalar.csv)?$~',$path,$m)){$batch=(new Import($this->db,$this->config))->get($m[1],$this->actor('catalog'));if(isset($m[2])){$lines=[['Satır','Stok kodu','Ürün adı','Hata']];foreach($batch['rows'] as $row)foreach($row['errors'] as $error)$lines[]=[$row['line'],$row['data']['sku'],$row['data']['name'],Import::errorLabel($error)];return new Response(Import::csv($lines),200,['Content-Type'=>'text/csv; charset=UTF-8','Content-Disposition'=>'attachment; filename=import-errors.csv']);}return $this->render('import-admin',['title'=>'İçe aktarma önizlemesi','rows'=>[],'columns'=>Import::COLUMNS,'batch'=>$batch]);}
        if($path==='/yonetim/tedarikciler'){$actor=$this->actor('settings');return $this->render('suppliers-admin',['title'=>'Tedarikçiler ve gönderim','data'=>(new Suppliers($this->db,$this->config))->listing($actor),'variants'=>$this->db->all('SELECT v.id,v.sku,v.fulfillment_mode,p.name FROM variants v JOIN products p ON p.id=v.product_id WHERE v.active=true ORDER BY v.sku LIMIT 200'),'countries'=>$this->db->all('SELECT code,name FROM country_rules ORDER BY name')]);}
        if(preg_match('~^/yonetim/tedarikci-paket/([A-Za-z0-9-]+)$~',$path,$m))return $this->render('supplier-group',['title'=>'Tedarikçi gönderimi','group'=>(new Suppliers($this->db,$this->config))->detail($m[1],$this->actor('settings'))]);
        if($path==='/yonetim/satin-alma'){$actor=$this->actor('purchases');return $this->render('purchases',['title'=>'Satın alma ve mal kabulü','rows'=>(new Purchasing($this->db,$this->config))->listing($actor),'suppliers'=>$this->db->all('SELECT id,name FROM suppliers WHERE archived=false ORDER BY name'),'variants'=>$this->db->all('SELECT v.id,v.sku,p.name,v.lot_tracking FROM variants v JOIN products p ON p.id=v.product_id WHERE v.active=true ORDER BY v.sku LIMIT 200')]);}
        if($path==='/yonetim/lotlar'){$this->actor('inventory');return $this->render('lots-admin',['title'=>'Lot ve geri çağırma','rows'=>$this->db->all("SELECT l.id,l.lot_number,l.expires_at,l.quarantined,l.recall_reference,v.sku,b.on_hand,b.quarantine FROM inventory_lots l JOIN variants v ON v.id=l.variant_id LEFT JOIN inventory_lot_balances b ON b.lot_id=l.id AND b.warehouse_id='main' ORDER BY l.created_at DESC LIMIT 100")]);}
        if(in_array($path,['/yonetim/roller','/yonetim/is-kuyrugu','/yonetim/islem-kaydi'],true)){$admin=new Administration($this->db,$this->config);$actor=$this->actor('settings');$section=['/yonetim/roller'=>'roles','/yonetim/is-kuyrugu'=>'jobs','/yonetim/islem-kaydi'=>'audit'][$path];return $this->render('administration',['title'=>'İşletme yönetimi','section'=>$section,'rows'=>match($section){'roles'=>$admin->users($actor),'jobs'=>$admin->jobs($actor),'audit'=>$admin->audit($actor)}]);}
        if($path==='/yonetim/raporlar'){$actor=$this->actor('finance');return $this->render('reports',['title'=>'Raporlar','report'=>(new Reporting($this->db,$this->config))->sales($r->query->get('currency','TRY'),$r->query->get('from'),$r->query->get('to'),$actor)]);}
        if($path==='/sitemap.xml')return new Response((new Seo($this->db,$this->config))->sitemap(),200,['Content-Type'=>'application/xml; charset=UTF-8']);
        if($path==='/yonetim/icerik')return $this->render('content-admin',['title'=>'İçerik yönetimi','rows'=>(new Content($this->db,$this->config))->admin($this->actor('content'))]);
        if($path==='/yonetim/hukuk'){$this->actor('settings');return $this->render('legal-admin',['title'=>'Hukuk metinleri','rows'=>$this->db->all('SELECT id,kind,locale,version,title,status,body,body_hash FROM legal_documents ORDER BY created_at DESC LIMIT 100')]);}
        if($path==='/yonetim/seo')return $this->render('seo-admin',['title'=>'SEO kontrolü','report'=>(new Seo($this->db,$this->config))->audit($this->actor('catalog'))]);
        if(preg_match('~^/(rehber|koleksiyon)/([a-z0-9-]+)$~',$path,$m)){$kind=$m[1]==='rehber'?'guide':'collection';$entry=(new Content($this->db,$this->config))->find($kind,$m[2],$this->locale);RuleViolation::ensure($entry,'NOT_FOUND','İçerik bulunamadı.',404);return $this->render('content',['title'=>$entry['title'],'entries'=>[$entry],'kind'=>$kind]);}
        if(in_array($path,['/rehber','/sss','/koleksiyonlar','/iletisim'],true)){$kind=['/rehber'=>'guide','/sss'=>'faq','/koleksiyonlar'=>'collection','/iletisim'=>'contact'][$path];return $this->render('content',['title'=>Lang::text(['guide'=>'guide','faq'=>'faq','collection'=>'collections','contact'=>'contact'][$kind],$this->locale),'entries'=>(new Content($this->db,$this->config))->listing($kind,$this->locale),'kind'=>$kind]);}
        if(in_array($path,['/hesap/adresler','/hesap/tercihler','/favoriler'],true)){if(!$this->principal)return new RedirectResponse($this->config->path(($this->locale==='en'?'/en':'').'/hesap'));$c=new Customers($this->db,$this->config);$section=['/hesap/adresler'=>'addresses','/hesap/tercihler'=>'preferences','/favoriler'=>'favorites'][$path];return $this->render('customer',['title'=>$this->locale==='tr'?'Hesabım':'My account','section'=>$section,'addresses'=>$section==='addresses'?$c->addresses($this->principal->id):[],'favorites'=>$section==='favorites'?$c->favorites($this->principal->id):[],'preferences'=>$section==='preferences'?$c->preferences($this->principal->id):[]]);}
        if($path==='/odeme/stripe'){$payment=(new Payments($this->db,$this->config))->start($r->query->get('order',''),$r->query->get('token'),$this->principal?->id);return new RedirectResponse($payment['url'],303);}
        if(preg_match('~^/yonetim/siparis/([A-Za-z0-9-]+)$~',$path,$m))return $this->render('staff-order',['title'=>'Sipariş işlemleri','detail'=>(new Fulfillment($this->db,$this->config))->detail($m[1],$this->actor('orders'))]);
        if($path==='/yonetim/iadeler'){$this->actor('returns');$rows=$this->db->all('SELECT r.id,r.order_id,r.variant_id,r.quantity,r.seal_status,r.status,r.disposition,o.number,i.name,i.fulfillment_source FROM returns r JOIN orders o ON o.id=r.order_id JOIN order_items i ON i.order_id=r.order_id AND i.variant_id=r.variant_id ORDER BY r.created_at DESC LIMIT 50');return $this->render('returns-admin',['title'=>'İade işlemleri','rows'=>$rows]);}
        if($path==='/')return $this->render('home',['title'=>'Tutkunu Keşfet.','products'=>$catalog->search()['rows']]);
        if($path==='/urunler'||preg_match('~^/kategori/([a-z0-9-]+)$~',$path,$m)){$filters=$r->query->all();if(isset($m[1]))$filters['category']=$m[1];return $this->render('catalog',['title'=>Lang::text('products',$this->locale),'catalog'=>$catalog->search($filters),'query'=>$r->query->get('q','')]);}
        if(preg_match('~^/urun/([a-z0-9-]+)$~',$path,$m)){$p=$catalog->product($m[1]);RuleViolation::ensure($p,'NOT_FOUND','Ürün bulunamadı.',404);return $this->render('product',['title'=>$this->locale==='en'?$p['name_en']:$p['name'],'product'=>$p,'seo'=>(new Seo($this->db,$this->config))->product($p['id'],$this->locale)]);}
        if($path==='/sepet')return $this->render('cart',['title'=>Lang::text('cart',$this->locale),'cart'=>$this->cart->get($this->cartToken,'TRY',$this->principal?->id)]);
        if($path==='/odeme'){$cart=$this->cart->get($this->cartToken,'TRY',$this->principal?->id);RuleViolation::ensure($cart['items'],'EMPTY_CART','Sepetinize ürün ekleyin.',400);$quote=$this->commerce->quote($this->cartToken,['country'=>'TR','currency'=>'TRY','locale'=>$this->locale],$this->principal?->id);return $this->render('checkout',['title'=>Lang::text('checkout_title',$this->locale),'cart'=>$cart,'quote'=>$quote]);}
        if($path==='/odeme/test'){$order=$this->commerce->order($r->query->get('order',''),$r->query->get('token'),$this->principal?->id);RuleViolation::ensure($order&&$this->config->local()&&$this->config->get('payment_provider')==='test','NOT_FOUND','Ödeme sayfası bulunamadı.',404);return $this->render('payment',['title'=>Lang::text('test_payment',$this->locale),'order'=>$order,'trackingToken'=>$r->query->get('token','')]);}
        if(preg_match('~^/siparis/([A-Za-z0-9-]+)$~',$path,$m)){$o=$this->commerce->order($m[1],$r->query->get('token'),$this->principal?->id);RuleViolation::ensure($o,'NOT_FOUND','Sipariş bulunamadı.',404);return $this->render('order',['title'=>Lang::text('order',$this->locale).' '.$o['number'],'order'=>$o,'trackingToken'=>$r->query->get('token',''),'shipments'=>$this->db->all('SELECT carrier,tracking_number,status FROM shipments WHERE order_id=? ORDER BY created_at',[$o['id']]),'returns'=>$this->db->all('SELECT id,status,quantity,variant_id FROM returns WHERE order_id=? ORDER BY created_at DESC',[$o['id']])]);}
        if(in_array($path,['/hesap','/yonetim/giris','/yonetim/mfa'],true)){$user=$this->auth->user($this->session);$orders=$this->principal?$this->db->all('SELECT id,number,status,total_minor,currency,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT 30',[$this->principal->id]):[];return $this->render('account',['title'=>Lang::text('account',$this->locale),'account'=>$user,'orders'=>$orders,'adminLogin'=>$path!=='/hesap']);}
        if($path==='/yonetim'||preg_match('~^/yonetim/(katalog|stok|siparisler|ayarlar|entegrasyonlar)$~',$path,$m)){
            if(!$this->principal)return new RedirectResponse($this->config->path('/yonetim/giris'));if(!$this->principal->mfa)return new RedirectResponse($this->config->path('/yonetim/mfa'));$section=$m[1]??match($this->principal->role){'warehouse'=>'stok','support','finance'=>'siparisler','marketing'=>'icerik',default=>'katalog'};if($section==='icerik')return new RedirectResponse($this->config->path('/yonetim/icerik'));$resource=['katalog'=>'catalog','stok'=>'inventory','siparisler'=>'orders','ayarlar'=>'settings','entegrasyonlar'=>'settings'][$section];$this->principal->require($resource);
            $rows=in_array($section,['katalog','stok'],true)?$catalog->admin($this->principal):($section==='siparisler'?$this->db->all('SELECT id,number,status,payment_status,fulfillment_status,created_at FROM orders ORDER BY created_at DESC LIMIT 100'):[]);return $this->render('admin',['title'=>'Yönetim','section'=>$section,'rows'=>$rows,'categories'=>$this->db->all('SELECT slug,name FROM categories ORDER BY name'),'sellerSettings'=>$section==='ayarlar'?(new Administration($this->db,$this->config))->sellerSettings($this->principal):[]]);
        }
        if(preg_match('~^/yasal/([a-z-]+)$~',$path,$m)){$kind=['gizlilik'=>'privacy','satis-kosullari'=>'terms','privacy'=>'privacy','terms'=>'terms'][$m[1]]??$m[1];$doc=$this->db->one("SELECT title,body FROM legal_documents WHERE kind=? AND locale=? AND status='effective' AND effective_at<=CURRENT_TIMESTAMP(3) AND(fixture=false OR ?=true) ORDER BY version DESC LIMIT 1",[$kind,$this->locale,$this->config->local()?1:0]);return $this->render('message',['title'=>$doc['title']??Lang::text('not_published',$this->locale),'message'=>$doc['body']??Lang::text('not_published',$this->locale)],$doc?200:404);}
        if(in_array($path,['/rehber','/sss','/iletisim','/koleksiyonlar','/favoriler'],true))return $this->render('message',['title'=>Lang::text(['/rehber'=>'guide','/sss'=>'faq','/iletisim'=>'contact','/koleksiyonlar'=>'collections','/favoriler'=>'selected'][$path],$this->locale),'message'=>Lang::text($path==='/iletisim'?'contact_empty':'not_published',$this->locale)]);
        if(in_array($path,['/hesap/parola-yenile','/hesap/dogrula'],true))return $this->render('reset',['title'=>Lang::text('reset',$this->locale),'verifyEmail'=>$path==='/hesap/dogrula']);
        throw new RuleViolation('NOT_FOUND','Sayfa bulunamadı.',404);
    }
    private function render(string $name,array $data=[],int $status=200):Response
    {
        $common=['locale'=>$this->locale,'basePath'=>$this->config->get('base_path'),'csrf'=>$this->csrf->getToken('write')->getValue(),'principal'=>$this->principal,'categories'=>$this->db->all('SELECT slug,name,name_en FROM categories WHERE active=true ORDER BY name'),'siteName'=>'SEXOGATE','canonical'=>$this->config->get('app_url')];return new Response($this->twig->render($name.'.twig',$data+$common),$status,['Content-Type'=>'text/html; charset=UTF-8']);
    }
